class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search_with_one_deletion(self, word):
        return self._search_with_one_deletion(word, 0, self.root)

    def _search_with_one_deletion(self, word, index, node):
        if index == len(word):
            return node.is_end_of_word

        for char in node.children:
            if self._search_with_one_deletion(word, index + 1, node.children[char]):
                return True

        return False

def find_typos(dictionary):
    trie = Trie()
    for word in dictionary:
        trie.insert(word)

    typos = []
    for word in dictionary:
        if trie.search_with_one_deletion(word):
            typos.append(word)

    return typos if typos else ["NO TYPOS"]

