    n = len(dictionary)
    words_set = set(dictionary)
    trie = {}

    def add_to_trie(word):
        node = trie
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node['end'] = True

    def search_in_trie(word):
        node = trie
        for char in word:
            if char not in node:
                return False
            node = node[char]
        return 'end' in node

    for word in dictionary:
        add_to_trie(word)

    typos = []
    for word in dictionary:
        for i in range(len(word)):
            new_word = word[:i] + word[i+1:]
            if new_word in words_set and search_in_trie(new_word):
                typos.append(word)
                break

    if not typos:
        return "NO TYPOS"
    else:
        return '\n'.join(typos)

